    def __init__(self , X,Y, padsz=40 ):
        self.X = X
        self.Y = Y
        self.padsz = padsz
    def __len__(self):
        return len(self.X)
    def __getitem__(self , index):
        x = self.X[index]
        y= self.Y[index]
        # Pad x to fixed size
        if len(x) < self.padsz:
            padded = torch.zeros(self.padsz)
            padded[:len(x)] = x
            x = padded
        elif len(x) > self.padsz:
            x = x[:self.padsz]
        return x,y
